CREATE OR REPLACE FUNCTION public.set_kaizen_person_code() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF TG_OP = 'UPDATE' THEN IF TG_TABLE_NAME = 'staff_profiles' THEN NEW.staff_code := OLD.staff_code; ELSIF TG_TABLE_NAME = 'sales_agents' THEN NEW.collaborator_code := OLD.collaborator_code; END IF; ELSIF TG_TABLE_NAME = 'staff_profiles' AND NEW.staff_code IS NULL THEN NEW.staff_code := 'KZ-NV-' || to_char(clock_timestamp(), 'YYMM') || '-' || lpad(nextval('public.kaizen_staff_code_seq')::text, 4, '0'); ELSIF TG_TABLE_NAME = 'sales_agents' AND NEW.collaborator_code IS NULL THEN NEW.collaborator_code := 'KZ-CTV-' || to_char(clock_timestamp(), 'YYMM') || '-' || lpad(nextval('public.kaizen_collaborator_code_seq')::text, 4, '0'); END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_staff_code_before_update BEFORE UPDATE ON public.staff_profiles FOR EACH ROW EXECUTE FUNCTION public.set_kaizen_person_code();
CREATE TRIGGER protect_collaborator_code_before_update BEFORE UPDATE ON public.sales_agents FOR EACH ROW EXECUTE FUNCTION public.set_kaizen_person_code();